import itertools

def solve_n2():
    n = 2
    nums = list(range(1, n*n + 1))
    count = 0
    for p in itertools.permutations(nums):
        a = [p[i:i+n] for i in range(0, n*n, n)]
        # check if good: a[i][j] + a[k][l] = a[i][l] + a[k][j]
        is_good = True
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    for l in range(n):
                        if a[i][j] + a[k][l] != a[i][l] + a[k][j]:
                            is_good = False
                            break
                    if not is_good: break
                if not is_good: break
            if not is_good: break
        if is_good:
            count += 1
    return count

def solve_n3():
    n = 3
    nums = list(range(1, n*n + 1))
    count = 0
    # itertools.permutations(nums) is 9! = 362880
    # This is small enough to run.
    for p in itertools.permutations(nums):
        a = [p[i:i+n] for i in range(0, n*n, n)]
        is_good = True
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    for l in range(n):
                        if a[i][j] + a[k][l] != a[i][l] + a[k][j]:
                            is_good = False
                            break
                    if not is_good: break
                if not is_good: break
            if not is_good: break
        if is_good:
            count += 1
    return count

print(f"n=2: {solve_n2()}")
print(f"n=3: {solve_n3()}")
